SELECT * FROM pos_order
WHERE deleted = 0

    AND customer_id = #{customerId}


    AND order_type = #{orderType}


    AND status = #{status}


    AND pay_status = #{payStatus}


    AND create_time >= #{startTime}


    AND create_time <= #{endTime}

ORDER BY create_time DESC
LIMIT #{offset}, #{limit}

SELECT * FROM pos_order
WHERE deleted = 0 AND customer_id = #{customerId}
ORDER BY create_time DESC

SELECT * FROM pos_order
WHERE deleted = 0
  AND create_time >= #{startTime}
  AND create_time <= #{endTime}
ORDER BY create_time DESC

SELECT pay_type AS payType, SUM(pay_amount) AS totalAmount, COUNT(*) AS count
FROM pos_order
WHERE deleted = 0
  AND create_time >= #{startTime}
  AND create_time <= #{endTime}
GROUP BY pay_type

SELECT order_type AS orderType, SUM(pay_amount) AS totalAmount, COUNT(*) AS count
FROM pos_order
WHERE deleted = 0
  AND create_time >= #{startTime}
  AND create_time <= #{endTime}
GROUP BY order_type
